{"metadata":{"kernelspec":{"language":"python","display_name":"Python 3","name":"python3"},"language_info":{"name":"python","version":"3.11.13","mimetype":"text/x-python","codemirror_mode":{"name":"ipython","version":3},"pygments_lexer":"ipython3","nbconvert_exporter":"python","file_extension":".py"},"kaggle":{"accelerator":"none","dataSources":[],"dockerImageVersionId":31089,"isInternetEnabled":true,"language":"python","sourceType":"script","isGpuEnabled":false}},"nbformat_minor":4,"nbformat":4,"cells":[{"cell_type":"code","source":"# %% [code]\n# %% [code]\n# %% [code]\nimport pandas as pd\nimport numpy as np\nfrom typing import Optional, List, Dict, Tuple, Sequence\nfrom sklearn.metrics import (\n    f1_score, roc_auc_score, average_precision_score, accuracy_score\n)\nimport math\nfrom sklearn.linear_model import Ridge\nfrom sklearn.neural_network import MLPClassifier\nfrom sklearn.preprocessing import StandardScaler\nfrom sklearn.pipeline import Pipeline\n\nfrom xgboost import XGBClassifier\nfrom catboost import CatBoostClassifier, Pool\n\nfrom dataclasses import dataclass\n\nimport torch\n\ndef chronological_purged_cv(\n    df: pd.DataFrame,\n    ts_col: str = \"Timestamp\",\n    n_splits: int = 5,\n    *,\n    test_fraction: float = 0.15,\n    test_rows: Optional[int] = None,\n    embargo: pd.Timedelta = pd.Timedelta(0),\n    min_test_rows: int = 1,\n    label_col: Optional[str] = None,\n    min_test_pos: int = 0,\n) -> List[Dict]:\n    \"\"\"\n    Chronological CV with **equal-row partitions** (by count), not equal time.\n\n    - Sort all rows by time.\n    - Split the *sorted index* into ``n_splits`` contiguous blocks with (approximately) the same number of rows.\n    - For each block, the test set is the **last `test_rows` rows** of the block. If ``test_rows`` is ``None``,\n      it uses ``ceil(test_fraction * block_size)``. A floor of ``min_test_rows`` is enforced.\n    - Training set = **all rows with timestamp < (test_start_time - embargo)** across the whole dataset.\n      This yields expanding, purged training windows and avoids any future leakage.\n    - If ``label_col`` is provided, the function will check the number of positives in each test set and warn\n      (or, if ``min_test_pos>0``, it will grow the test set backwards within the block to try to reach the target.\n      If it still cannot, it keeps the maximal available block and warns.)\n\n    Returns a list of dicts per fold with indices and date ranges.\n    \"\"\"\n    if ts_col not in df.columns:\n        raise KeyError(f\"{ts_col} not in dataframe\")\n\n    d = df[[ts_col]].dropna(subset=[ts_col])\n    if d.empty:\n        raise ValueError(\"No non-null timestamps available after parsing.\")\n\n    # Global sorted index by time\n    order = d[ts_col].sort_values().index\n    ts_sorted = df.loc[order, ts_col]\n\n    n = len(order)\n    if n_splits <= 0:\n        raise ValueError(\"n_splits must be >= 1\")\n    if n_splits > n:\n        raise ValueError(\"n_splits cannot exceed number of rows\")\n\n    # Row-quantile boundaries\n    cuts = np.linspace(0, n, n_splits + 1, dtype=int)\n\n    folds: List[Dict] = []\n    for i in range(n_splits):\n        lo, hi = cuts[i], cuts[i + 1]\n        part_idx = order[lo:hi]\n        if len(part_idx) == 0:\n            continue\n\n        part_start_time = df.loc[part_idx[0], ts_col]\n        part_end_time   = df.loc[part_idx[-1], ts_col]\n\n        block_size = len(part_idx)\n        desired_test = test_rows if test_rows is not None else int(np.ceil(test_fraction * block_size))\n        desired_test = max(desired_test, min_test_rows)\n        desired_test = min(desired_test, block_size)  # cannot exceed block size\n\n        # Select last `desired_test` rows of the block as test\n        test_idx = part_idx[-desired_test:]\n        test_start_time = df.loc[test_idx[0], ts_col]\n        test_end_time   = df.loc[test_idx[-1], ts_col]\n\n        # If label constraint provided, try to widen within the block\n        if label_col is not None and min_test_pos > 0 and label_col in df.columns:\n            pos_count = int(df.loc[test_idx, label_col].sum())\n            if pos_count < min_test_pos:\n                # widen backwards inside the block\n                need = min_test_pos - pos_count\n                # grow by chunks of 5% of the block or at least 100 rows each step\n                step = max(100, block_size // 20)\n                take = desired_test\n                while pos_count < min_test_pos and take < block_size:\n                    take = min(block_size, take + step)\n                    test_idx = part_idx[-take:]\n                    pos_count = int(df.loc[test_idx, label_col].sum())\n                test_start_time = df.loc[test_idx[0], ts_col]\n                test_end_time   = df.loc[test_idx[-1], ts_col]\n                if pos_count < min_test_pos:\n                    print(\n                        f\"Warning: fold {i+1} reached only {pos_count} positives (< {min_test_pos}) \"\n                        f\"with entire block of {block_size} rows.\"\n                    )\n        elif label_col is not None and label_col not in df.columns:\n            print(f\"Warning: label_col '{label_col}' not found; skipping min_test_pos checks.\")\n\n        # Training: all rows strictly before (test_start_time - embargo)\n        train_cut_time = test_start_time - embargo\n        train_mask = ts_sorted < train_cut_time\n        train_idx = ts_sorted.index[train_mask]\n\n        folds.append(\n            dict(\n                fold=i + 1,\n                train_idx=train_idx,\n                test_idx=test_idx,\n                part_start=part_start_time,\n                part_end=part_end_time,\n                test_start=test_start_time,\n                test_end=test_end_time,\n                train_end=train_cut_time,\n                n_train=len(train_idx),\n                n_test=len(test_idx),\n            )\n        )\n\n    if len(folds) < n_splits:\n        print(\n            f\"Warning: produced {len(folds)} folds (requested {n_splits}). Some partitions were empty.\"\n        )\n\n    return folds\n\n\n\n\n\n\n\nclass FeatureEngineer:\n    \"\"\"\n    Fit on a training DataFrame to discover:\n      - top‐k high‐risk sender & receiver banks\n      - top‐k high‐risk currencies\n      - all payment‐format categories\n    Then transform any DataFrame by:\n      - log(Amount Received)\n      - fee flag & fee pct\n      - cyclical time features\n      - internal/external transfer flags\n      - one‐hot Payment Format\n      - binary high‐risk flags (banks & currencies)\n    \"\"\"\n    def __init__(self,\n                 top_k_banks: int = 10,\n                 top_k_currencies: int = 6,\n                 target_col: str = \"Is Laundering\",\n                 ts_col: str = \"Timestamp\"):\n        self.top_k_banks = top_k_banks\n        self.top_k_currencies = top_k_currencies\n        self.target_col = target_col\n        self.ts_col = ts_col\n\n    def fit(self, df: pd.DataFrame):\n        # 1) Ensure timestamp\n        df = df.copy()\n        \n        df[\"Timestamp\"] = pd.to_datetime(\n                df[\"Timestamp\"],\n                format=\"%Y/%m/%d %H:%M\",   \n                errors=\"coerce\"\n        )\n        \n        df[self.ts_col] = pd.to_datetime(df[self.ts_col], \n                                         format=\"%Y/%m/%d %H:%M\",\n                                         errors=\"coerce\")\n        \n        # 2) Learn high‐risk banks\n        sender_rates = (\n            df.groupby(\"From Bank\")[self.target_col]\n              .mean()\n              .nlargest(self.top_k_banks)\n        )\n        receiver_rates = (\n            df.groupby(\"To Bank\")[self.target_col]\n              .mean()\n              .nlargest(self.top_k_banks)\n        )\n        self.high_risk_senders   = set(sender_rates.index)\n        self.high_risk_receivers = set(receiver_rates.index)\n\n        # 3) Learn high‐risk currencies (combine receive+payment)\n        cur_df = pd.concat([\n            df[[\"Receiving Currency\", self.target_col]]\n               .rename(columns={\"Receiving Currency\":\"Currency\"}),\n            df[[\"Payment Currency\",   self.target_col]]\n               .rename(columns={\"Payment Currency\":  \"Currency\"})\n        ])\n        currency_rates = (\n            cur_df.groupby(\"Currency\")[self.target_col]\n                  .mean()\n                  .nlargest(self.top_k_currencies)\n        )\n        self.high_risk_currencies = set(currency_rates.index)\n\n        # 4) Remember all seen payment formats\n        self.payment_formats = df[\"Payment Format\"].dropna().unique().tolist()\n\n        return self\n\n    def transform(self, df: pd.DataFrame) -> pd.DataFrame:\n        df = df.copy()\n        # — 1) Timestamp → cyclical features\n        df[self.ts_col] = pd.to_datetime(df[self.ts_col], \n                                         format=\"%Y/%m/%d %H:%M\",\n                                         errors=\"coerce\")\n        h = df[self.ts_col].dt.hour.fillna(0).astype(int)\n        dow = df[self.ts_col].dt.dayofweek.fillna(0).astype(int)\n        df[\"tod_sin\"] = np.sin(2 * np.pi * h / 24)\n        df[\"tod_cos\"] = np.cos(2 * np.pi * h / 24)\n        df[\"dow_sin\"] = np.sin(2 * np.pi * dow / 7)\n        df[\"dow_cos\"] = np.cos(2 * np.pi * dow / 7)\n\n        # — 2) Amount features\n        df[\"Amount Received\"] = pd.to_numeric(df[\"Amount Received\"], errors=\"coerce\")\n        df[\"log_amount_received\"] = np.log1p(df[\"Amount Received\"])\n        # fee flag & fee pct\n        df[\"Amount Paid\"] = pd.to_numeric(df[\"Amount Paid\"], errors=\"coerce\")\n        df[\"fee_flag\"] = (df[\"Amount Paid\"] != df[\"Amount Received\"]).astype(int)\n        df[\"fee_pct\"]  = ((df[\"Amount Paid\"] - df[\"Amount Received\"]) \n                          / df[\"Amount Received\"]\n                         ).fillna(0)\n\n        # — 3) Transfer flags\n        df[\"internal_transfer\"] = (df[\"From Bank\"] == df[\"To Bank\"]).astype(int)\n        df[\"external_transfer\"] = (df[\"From Bank\"] != df[\"To Bank\"]).astype(int)\n\n        # — 4) High-risk bank flags\n        df[\"high_risk_sender\"] = df[\"From Bank\"].isin(self.high_risk_senders).astype(int)\n        df[\"high_risk_receiver\"] = df[\"To Bank\"].isin(self.high_risk_receivers).astype(int)\n\n        # — 5) High-risk currency flag\n        # Check both Receive & Payment\n        df[\"high_risk_currency\"] = (\n            df[\"Receiving Currency\"].isin(self.high_risk_currencies) |\n            df[\"Payment Currency\"].isin(self.high_risk_currencies)\n        ).astype(int)\n\n        # — 6) One-hot Payment Format (guaranteed same columns as training)\n        for fmt in self.payment_formats:\n            col = f\"pf_{fmt}\"\n            df[col] = (df[\"Payment Format\"] == fmt).astype(int)\n\n        columns_to_drop = [\n\n            'Account',\n            'Account.1',\n            'From Bank',\n            'To Bank',\n            'Amount Received',\n            'Payment Format',\n            'Payment Currency',\n            'Receiving Currency',\n            'Timestamp'\n        ]\n        \n        df.drop(columns_to_drop, axis = 1, inplace = True)\n\n        return df\n\n    def fit_transform(self, df: pd.DataFrame) -> pd.DataFrame:\n        return self.fit(df).transform(df)\n\n\ndef summarise(scores):\n    df = pd.DataFrame(scores)\n    return df.describe().loc[[\"mean\",\"std\",\"min\",\"max\"]].round(4)\n\ndef evaluate(true, prob, thr=0.5):\n    pred = (prob >= thr).astype(int)\n    return dict(\n        f1          = f1_score(true, pred),\n        roc_auc     = roc_auc_score(true, prob),\n        pr_auc      = average_precision_score(true, prob),\n        accuracy    = accuracy_score(true, pred)\n    )\n\n\n####Conventional ML Benchmarking Functions#####\n\ndef chronological_blend_split(\n    df: pd.DataFrame,\n    ts_col: str,\n    blend_fraction: float,\n    embargo: pd.Timedelta\n) -> Tuple[pd.DataFrame, pd.DataFrame]:\n    \"\"\"\n    Split a training fold chronologically into:\n      - train_early: earliest rows (to fit base models)\n      - train_blend: last 'blend_fraction' rows (to fit Ridge meta)\n    An embargo is enforced between the two to avoid leakage.\n    \"\"\"\n    if not (0.05 <= blend_fraction <= 0.35):\n        raise ValueError(\"blend_fraction should be between 0.05 and 0.35\")\n\n    order = df[ts_col].sort_values().index\n    n = len(order)\n    b = max(1, int(math.ceil(n * blend_fraction)))\n\n    blend_idx = order[-b:]\n    blend_start_time = df.loc[blend_idx[0], ts_col]\n\n    cutoff_time = blend_start_time - embargo\n    early_mask = df[ts_col] < cutoff_time\n    early_idx = df.index[early_mask]\n\n    train_early = df.loc[early_idx].reset_index(drop=True)\n    train_blend = df.loc[blend_idx].reset_index(drop=True)\n    if len(train_early) == 0:\n        raise ValueError(\"Embargo too large vs. data—no rows left for train_early.\")\n    return train_early, train_blend\n\n\ndef build_stack_components(\n    trial: Optional[\"optuna.trial.Trial\"] = None,\n    seed: int = 12,\n    use_gpu: bool = False\n) -> Tuple[XGBClassifier, CatBoostClassifier, Pipeline, Ridge, float]:\n    \"\"\"\n    Create base learners (XGB, CatBoost, MLP), Ridge meta-learner, and pick blend_fraction.\n    If `trial` is None, returns sensible defaults aligned with your earlier tests.\n    \"\"\"\n    if trial is None:\n        xgb = XGBClassifier(\n            n_estimators=400, max_depth=6, eta=0.05,\n            subsample=0.8, colsample_bytree=0.8,\n            min_child_weight=1.0,\n            objective=\"binary:logistic\", eval_metric=\"auc\",\n            tree_method=\"hist\", \n            device = 'cuda' if use_gpu else 'cpu',\n            random_state=seed\n        )\n        cat = CatBoostClassifier(\n            iterations=700, depth=6, learning_rate=0.05,\n            l2_leaf_reg=3.0,\n            loss_function=\"Logloss\", eval_metric=\"AUC\",\n            verbose=False, task_type=\"GPU\" if use_gpu else \"CPU\", \n            devices = \"0\" if use_gpu else None, random_seed=seed\n        )\n        mlp = Pipeline(steps=[\n            (\"scaler\", StandardScaler(with_mean=False)),\n            (\"mlp\", MLPClassifier(\n                hidden_layer_sizes=(128, 64),\n                activation=\"relu\",\n                solver=\"adam\",\n                batch_size=1024,\n                learning_rate_init=1e-3,\n                max_iter=30,\n                alpha=1e-6,\n                random_state=seed\n            ))\n        ])\n        ridge = Ridge(alpha=1.0, fit_intercept=True, random_state=seed)\n        blend_fraction = 0.15\n        return xgb, cat, mlp, ridge, blend_fraction\n\n    # --- With Optuna trial (search space) ---\n    xgb = XGBClassifier(\n        n_estimators=trial.suggest_int(\"xgb_n_estimators\", 300, 1200, step=100),\n        max_depth=trial.suggest_int(\"xgb_max_depth\", 3, 9),\n        eta=trial.suggest_float(\"xgb_eta\", 0.01, 0.2, log=True),\n        subsample=trial.suggest_float(\"xgb_subsample\", 0.6, 1.0),\n        colsample_bytree=trial.suggest_float(\"xgb_colsample_bytree\", 0.6, 1.0),\n        min_child_weight=trial.suggest_float(\"xgb_min_child_weight\", 1.0, 8.0),\n        reg_lambda=trial.suggest_float(\"xgb_reg_lambda\", 1e-3, 10.0, log=True),\n        reg_alpha=trial.suggest_float(\"xgb_reg_alpha\", 1e-6, 1.0, log=True),\n        objective=\"binary:logistic\",\n        eval_metric=\"auc\",\n        tree_method= \"hist\",\n        device = 'cuda' if use_gpu else 'cpu',\n        random_state=seed\n    )\n\n    cat = CatBoostClassifier(\n        iterations=trial.suggest_int(\"cat_iterations\", 300, 1500, step=100),\n        depth=trial.suggest_int(\"cat_depth\", 4, 10),\n        learning_rate=trial.suggest_float(\"cat_lr\", 0.01, 0.2, log=True),\n        l2_leaf_reg=trial.suggest_float(\"cat_l2_leaf_reg\", 1.0, 10.0),\n        loss_function=\"Logloss\",\n        eval_metric=\"AUC\",\n        verbose=False,\n        task_type=\"GPU\" if use_gpu else \"CPU\",\n        devices = \"0\" if use_gpu else None,\n        random_seed=seed\n    )\n\n    mlp = Pipeline(steps=[\n        (\"scaler\", StandardScaler(with_mean=False)),\n        (\"mlp\", MLPClassifier(\n            hidden_layer_sizes=(\n                trial.suggest_int(\"mlp_h1\", 64, 256, step=32),\n                trial.suggest_int(\"mlp_h2\", 32, 128, step=32),\n            ),\n            activation=\"relu\",\n            solver=\"adam\",\n            batch_size=trial.suggest_categorical(\"mlp_batch\", [512, 1024, 2048]),\n            learning_rate_init=trial.suggest_float(\"mlp_lr\", 1e-4, 5e-3, log=True),\n            max_iter=trial.suggest_int(\"mlp_max_iter\", 20, 60, step=5),\n            alpha=trial.suggest_float(\"mlp_alpha\", 1e-6, 1e-2, log=True),\n            random_state=seed\n        ))\n    ])\n\n    ridge = Ridge(\n        alpha=trial.suggest_float(\"ridge_alpha\", 1e-3, 10.0, log=True),\n        fit_intercept=True,\n        random_state=seed\n    )\n    blend_fraction = trial.suggest_float(\"blend_fraction\", 0.08, 0.25)\n    return xgb, cat, mlp, ridge, blend_fraction\n\n\ndef apply_best_params_to_defaults(\n    best_params: Dict,\n    seed: int = 42\n) -> Tuple[XGBClassifier, CatBoostClassifier, Pipeline, Ridge, float]:\n    \"\"\"\n    Start from defaults and apply a best-params dict (from Optuna study.best_trial.params).\n    Returns configured models and blend_fraction.\n    \"\"\"\n    xgb, cat, mlp, ridge, blend_fraction = build_stack_components(None, seed=seed)\n\n    # XGB\n    mapping = {\n        \"xgb_n_estimators\": \"n_estimators\",\n        \"xgb_max_depth\": \"max_depth\",\n        \"xgb_eta\": \"eta\",\n        \"xgb_subsample\": \"subsample\",\n        \"xgb_colsample_bytree\": \"colsample_bytree\",\n        \"xgb_min_child_weight\": \"min_child_weight\",\n        \"xgb_reg_lambda\": \"reg_lambda\",\n        \"xgb_reg_alpha\": \"reg_alpha\",\n    }\n    for k_src, k_dst in mapping.items():\n        if k_src in best_params:\n            xgb.set_params(**{k_dst: best_params[k_src]})\n\n    # CatBoost\n    if \"cat_iterations\" in best_params: cat.set_params(iterations=best_params[\"cat_iterations\"])\n    if \"cat_depth\" in best_params:      cat.set_params(depth=best_params[\"cat_depth\"])\n    if \"cat_lr\" in best_params:         cat.set_params(learning_rate=best_params[\"cat_lr\"])\n    if \"cat_l2_leaf_reg\" in best_params:cat.set_params(l2_leaf_reg=best_params[\"cat_l2_leaf_reg\"])\n\n    # MLP\n    mlp_updates = {}\n    if \"mlp_h1\" in best_params or \"mlp_h2\" in best_params:\n        h1 = best_params.get(\"mlp_h1\", 128)\n        h2 = best_params.get(\"mlp_h2\", 64)\n        mlp_updates[\"mlp__hidden_layer_sizes\"] = (h1, h2)\n    if \"mlp_batch\" in best_params:\n        mlp_updates[\"mlp__batch_size\"] = best_params[\"mlp_batch\"]\n    if \"mlp_lr\" in best_params:\n        mlp_updates[\"mlp__learning_rate_init\"] = best_params[\"mlp_lr\"]\n    if \"mlp_max_iter\" in best_params:\n        mlp_updates[\"mlp__max_iter\"] = best_params[\"mlp_max_iter\"]\n    if \"mlp_alpha\" in best_params:\n        mlp_updates[\"mlp__alpha\"] = best_params[\"mlp_alpha\"]\n    if mlp_updates:\n        mlp.set_params(**mlp_updates)\n\n    # Ridge + blend split\n    if \"ridge_alpha\" in best_params:\n        ridge.set_params(alpha=best_params[\"ridge_alpha\"])\n    if \"blend_fraction\" in best_params:\n        blend_fraction = best_params[\"blend_fraction\"]\n\n    return xgb, cat, mlp, ridge, blend_fraction\n\n\ndef train_stack_and_eval_single_fold(\n    train_df: pd.DataFrame,\n    test_df: pd.DataFrame,\n    embargo: pd.Timedelta,\n    *,\n    xgb: XGBClassifier,\n    cat: CatBoostClassifier,\n    mlp: Pipeline,\n    meta: Ridge,\n    blend_fraction: float,\n    ts_col: str = \"Timestamp\",\n    target_col: str = \"Is Laundering\",\n) -> Tuple[Dict, Dict]:\n    \"\"\"\n    Workflow per outer fold:\n      1) Fit FeatureEngineer on outer-train only\n      2) Chronological blend split within train_df (with embargo)\n      3) Fit base models on train_early; fit Ridge on blend predictions\n      4) Refit base models on full train_df; predict test; combine via Ridge\n    Returns: (metrics_by_model, raw_preds)\n    \"\"\"\n    # 1) Fit FE on outer train only\n    fe = FeatureEngineer(\n        top_k_banks=30,\n        top_k_currencies=10,\n        target_col=target_col,\n        ts_col=ts_col\n    )\n    fe.fit(train_df)\n\n    # 2) Blend split\n    train_early, train_blend = chronological_blend_split(\n        train_df, ts_col=ts_col, blend_fraction=blend_fraction, embargo=embargo\n    )\n\n    # Transform\n    X_early = fe.transform(train_early).copy()\n    X_blend = fe.transform(train_blend).copy()\n    X_test  = fe.transform(test_df).copy()\n\n    y_early = X_early.pop(target_col).values\n    y_blend = X_blend.pop(target_col).values\n    y_test  = X_test.pop(target_col).values\n\n    # 3) Fit base models on early part\n    xgb.fit(X_early, y_early)\n    cat.fit(Pool(X_early, y_early))  # engineered features are numeric; cat_features=[]\n    mlp.fit(X_early, y_early)\n\n    P_blend = np.column_stack([\n        xgb.predict_proba(X_blend)[:, 1],\n        cat.predict_proba(X_blend)[:, 1],\n        mlp.predict_proba(X_blend)[:, 1],\n    ])\n    meta.fit(P_blend, y_blend)\n\n    # 4) Refit base models on full training fold\n    X_train_full = fe.transform(train_df).copy()\n    y_train_full = X_train_full.pop(target_col).values\n    xgb.fit(X_train_full, y_train_full)\n    cat.fit(Pool(X_train_full, y_train_full))\n    mlp.fit(X_train_full, y_train_full)\n\n    # Test predictions\n    p_xgb = xgb.predict_proba(X_test)[:, 1]\n    p_cat = cat.predict_proba(X_test)[:, 1]\n    p_mlp = mlp.predict_proba(X_test)[:, 1]\n    P_test = np.column_stack([p_xgb, p_cat, p_mlp])\n\n    p_ens = meta.predict(P_test).clip(0.0, 1.0)\n\n    # Use your existing evaluate()\n    out = {\n        \"ensemble\": evaluate(y_test, p_ens),\n        \"xgb\":      evaluate(y_test, p_xgb),\n        \"cat\":      evaluate(y_test, p_cat),\n        \"mlp\":      evaluate(y_test, p_mlp),\n    }\n    raw = {\"y_test\": y_test, \"p_ens\": p_ens, \"p_xgb\": p_xgb, \"p_cat\": p_cat, \"p_mlp\": p_mlp}\n    return out, raw\n\n\n\n\n###GNN Helper Functions###\n\ndef build_account_index(df: pd.DataFrame,\n                        src_col: str = \"Account\",\n                        dst_col: str = \"Account.1\") -> Tuple[Dict, np.ndarray, int]:\n    \"\"\"\n    Build a stable mapping (account_id -> node_index) across the whole dataset.\n    Returns (aid2idx, idx2aid, num_nodes).\n    \"\"\"\n    accounts = pd.unique(df[[src_col, dst_col]].values.ravel())\n    aid2idx = {aid: i for i, aid in enumerate(accounts)}\n    idx2aid = np.array(accounts, dtype=object)\n    return aid2idx, idx2aid, len(aid2idx)\n\n# ---------- Lightweight time/categorical/amount features ----------\ndef add_basic_temporal_feats(df: pd.DataFrame,\n                             ts_col: str = \"Timestamp\",\n                             amt_col: str = \"Amount Paid\",\n                             out_log_col: str = \"Log_amount\") -> pd.DataFrame:\n    \"\"\"\n    - ensure Timestamp\n    - log1p(Amount Paid)\n    - time-of-day sin/cos\n    \"\"\"\n    df = df.copy()\n    df[ts_col] = pd.to_datetime(df[ts_col], format=\"%Y/%m/%d %H:%M\", errors=\"coerce\")\n    df[out_log_col] = np.log1p(pd.to_numeric(df[amt_col], errors=\"coerce\").fillna(0.0))\n    tod = (\n        df[ts_col].dt.hour * 3600\n        + df[ts_col].dt.minute * 60\n        + df[ts_col].dt.second\n    ).fillna(0).astype(int)\n    df[\"tod_sin\"] = np.sin(2 * np.pi * tod / 86_400)\n    df[\"tod_cos\"] = np.cos(2 * np.pi * tod / 86_400)\n    return df\n\ndef rolling_sums_pandas(df: pd.DataFrame,\n                        windows: Sequence[pd.Timedelta],\n                        ts_col: str = \"Timestamp\",\n                        amt_col: str = \"Amount Paid\",\n                        src_col: str = \"Account\",\n                        dst_col: str = \"Account.1\") -> pd.DataFrame:\n    \"\"\"\n    Returns 2×len(windows) columns:\n        src_sum_<hours>h, dst_sum_<hours>h\n    Each sum excludes the current transaction (shift(1)).\n    \"\"\"\n    out = pd.DataFrame(index=df.index)\n    long = (\n        pd.concat(\n            [\n                df.assign(role=\"src\", account=df[src_col]),\n                df.assign(role=\"dst\", account=df[dst_col]),\n            ],\n            ignore_index=True,\n        )\n        .sort_values([\"account\", ts_col])\n    )\n    long[amt_col] = pd.to_numeric(long[amt_col], errors=\"coerce\").astype(\"float32\").fillna(0.0)\n    long = long.set_index(ts_col)\n\n    for w in windows:\n        hours = int(w.total_seconds() // 3600)\n        roll = (\n            long.groupby(\"account\")[amt_col]\n            .rolling(w)\n            .sum()\n            .shift(1)  # exclude current tx\n            .reset_index(level=0, drop=True)\n        )\n        out[f\"src_sum_{hours}h\"] = roll[long[\"role\"].eq(\"src\")].values\n        out[f\"dst_sum_{hours}h\"] = roll[long[\"role\"].eq(\"dst\")].values\n\n    return out.fillna(0.0).astype(\"float32\")\n\ndef encode_categories_inplace(df: pd.DataFrame,\n                              cat_cols: Sequence[str]) -> Dict[str, int]:\n    \"\"\"\n    In-place categorical encoding with .cat.codes.\n    Returns vocab sizes per column.\n    \"\"\"\n    vocabs = {}\n    for col in cat_cols:\n        df[col] = df[col].astype(\"category\")\n        df[col] = df[col].cat.codes.astype(\"int32\")\n        vocabs[col] = int(df[col].nunique())\n    return vocabs\n\n# ---------- CV → time-ordered slices for streaming eval ----------\ndef time_order_slices(folds: List[Dict],\n                      df: pd.DataFrame,\n                      ts_col: str = \"Timestamp\") -> List[Dict]:\n    \"\"\"\n    Given chronological_purged_cv folds based on original indices, produce for each fold:\n    - train_slice: [0, max(train_pos)+1)\n    - val_slice:   [train_end, test_start)\n    - test_slice:  [min(test_pos), max(test_pos)+1)\n    Slices are in the **time-sorted** order of df.\n    \"\"\"\n    ts_seconds = (pd.to_datetime(df[ts_col]).astype(\"int64\") // 10**9).values\n    order_np = np.argsort(ts_seconds)\n    pos_of_idx = {orig_idx: new_pos for new_pos, orig_idx in enumerate(order_np)}\n\n    for f in folds:\n        train_pos = [pos_of_idx[i] for i in f[\"train_idx\"]]\n        test_pos  = [pos_of_idx[i] for i in f[\"test_idx\"]]\n        f[\"train_slice\"] = slice(0, max(train_pos) + 1)\n        f[\"test_slice\"]  = slice(min(test_pos), max(test_pos) + 1)\n        train_end  = f[\"train_slice\"].stop\n        test_start = f[\"test_slice\"].start\n        f[\"val_slice\"] = slice(train_end, test_start)\n    return folds\n\n# ---------- Edge tensor packer ----------\n@dataclass\nclass EdgePack:\n    src_nodes: torch.Tensor\n    dst_nodes: torch.Tensor\n    edge_ts:   torch.Tensor\n    edge_attr: torch.Tensor\n    y:         torch.Tensor\n    cat_tensors: Dict[str, torch.Tensor]\n    order:     torch.Tensor\n    scaler:    StandardScaler\n    feat_dim:  int\n    vocabs:    Dict[str, int]\n\ndef prepare_temporal_edge_tensors(\n    df: pd.DataFrame,\n    aid2idx: Dict,\n    edge_feat_cols: Sequence[str],\n    cat_cols: Sequence[str],\n    label_col: str = \"Is Laundering\",\n    ts_col: str = \"Timestamp\",\n    src_col: str = \"Account\",\n    dst_col: str = \"Account.1\",\n    scaler: Optional[StandardScaler] = None\n) -> EdgePack:\n    \"\"\"\n    - sort all edges by time\n    - numeric edge features scaled via StandardScaler\n    - map (src,dst) to node indices\n    - pack categorical edge fields (already encoded as int codes)\n    - return tensors on CPU (caller can .to(device))\n    \"\"\"\n    d = df.copy()\n    # sort by time\n    d[ts_col] = pd.to_datetime(d[ts_col], errors=\"coerce\")\n    d = d.sort_values(ts_col).reset_index(drop=True)\n\n    # scale numeric edge features\n    if scaler is None:\n        scaler = StandardScaler()\n        d[edge_feat_cols] = scaler.fit_transform(d[edge_feat_cols])\n    else:\n        d[edge_feat_cols] = scaler.transform(d[edge_feat_cols])\n\n    # map accounts → indices\n    src_nodes = d[src_col].map(aid2idx).astype(\"int64\").values\n    dst_nodes = d[dst_col].map(aid2idx).astype(\"int64\").values\n\n    # pack tensors\n    edge_ts   = (d[ts_col].astype(\"int64\").values // 10**9).astype(\"int64\")\n    edge_attr = d[edge_feat_cols].astype(\"float32\").values\n    y         = d[label_col].astype(\"float32\").values\n\n    cat_tensors = {c: torch.tensor(d[c].values.astype(\"int64\")) for c in cat_cols}\n    vocabs      = {c: int(d[c].max()) + 1 if len(d) > 0 else 0 for c in cat_cols}\n\n    src_nodes = torch.tensor(src_nodes, dtype=torch.long)\n    dst_nodes = torch.tensor(dst_nodes, dtype=torch.long)\n    edge_ts   = torch.tensor(edge_ts,   dtype=torch.long)\n    edge_attr = torch.tensor(edge_attr, dtype=torch.float32)\n    y         = torch.tensor(y,         dtype=torch.float32)\n\n    order = torch.arange(len(d))  # already sorted\n\n    return EdgePack(\n        src_nodes=src_nodes, dst_nodes=dst_nodes,\n        edge_ts=edge_ts, edge_attr=edge_attr, y=y,\n        cat_tensors=cat_tensors, order=order,\n        scaler=scaler, feat_dim=edge_attr.shape[1], vocabs=vocabs\n    )\n\n# ---------- Streaming/batched training helpers ----------\nclass ChronoIter:\n    \"\"\"Iterate over a contiguous slice [s:e) in fixed-size batches.\"\"\"\n    def __init__(self, slc: slice, batch_size: int):\n        self.s, self.e, self.b = slc.start, slc.stop, batch_size\n    def __iter__(self):\n        p = self.s\n        while p < self.e:\n            q = min(p + self.b, self.e)\n            yield slice(p, q)\n            p = q\n\ndef hard_reset_tgn_memory(mem, device: torch.device, raw_msg_dim: int):\n    \"\"\"\n    For TGN-like memories: clear all state and seed per-node msg stores\n    with a safe dummy message at time 0.\n    - `mem` must implement `.reset_state()`, `.num_nodes`\n    - The notebook architectures are responsible for attaching `memory`.\n    \"\"\"\n    mem.reset_state()\n    # Pre-allocate dummy stores if attributes exist\n    if hasattr(mem, \"msg_s_store\") and hasattr(mem, \"msg_d_store\"):\n        mem.msg_s_store = {}\n        mem.msg_d_store = {}\n        for i in range(mem.num_nodes):\n            nid  = torch.tensor([i], device=device)\n            t0   = torch.zeros(1, dtype=torch.long, device=device)\n            raw0 = torch.zeros((1, raw_msg_dim), dtype=torch.float32, device=device)\n            mem.msg_s_store[i] = (nid.clone(), nid.clone(), t0.clone(), raw0.clone())\n            mem.msg_d_store[i] = (nid.clone(), nid.clone(), t0.clone(), raw0.clone())\n\n@torch.no_grad()\ndef compute_pos_weight(y: torch.Tensor, slc: slice) -> torch.Tensor:\n    \"\"\"\n    For BCEWithLogitsLoss(pos_weight=...).\n    pos_weight = (#neg / #pos) in the training window.\n    \"\"\"\n    y_slice = y[slc]\n    pos = (y_slice == 1).sum()\n    neg = (y_slice == 0).sum()\n    if pos == 0:\n        return torch.tensor(1.0)  # fallback\n    return (neg.float() / pos.float()).clamp(min=1.0)\n\ndef run_epoch_streaming(\n    model,\n    pack: EdgePack,\n    slc: slice,\n    criterion,\n    optimizer: Optional[torch.optim.Optimizer],\n    batch_size: int,\n    device: torch.device,\n    detach_readout: bool = True,       # kept for API compatibility\n    memory_reset_on_eval: bool = True,\n) -> Tuple[torch.Tensor, torch.Tensor, float]:\n    \"\"\"\n    Single pass over a time-ordered edge slice using batches.\n    If optimizer is None: eval-only pass; optionally resets memory at start.\n    Assumes model(src, dst, t, edge_attr, **cat_inputs) -> (logit, raw_msg)\n    \"\"\"\n    training = optimizer is not None\n\n    # Reset memory at start of EVAL pass (to avoid leakage & stale device state)\n    if (not training) and memory_reset_on_eval and hasattr(model, \"memory\"):\n        # your helper should clear stores and move buffers to `device`\n        hard_reset_tgn_memory(model.memory, device, getattr(model, \"raw_msg_dim\", None))\n\n    # Keep the big tensors on CPU; we'll slice then move per-batch:\n    src_all, dst_all = pack.src_nodes, pack.dst_nodes\n    ts_all,  x_all   = pack.edge_ts,  pack.edge_attr\n    y_all            = pack.y\n    cat_all          = pack.cat_tensors  # dict[str, Tensor]\n\n    preds, labels = [], []\n    total_loss, n = 0.0, 0\n\n    for sub in ChronoIter(slc, batch_size):\n        bsz = sub.stop - sub.start\n        if bsz == 0:\n            continue  # skip empty micro-batch\n\n        # ---- move this micro-batch to the model's device ----\n        src_b = src_all[sub].to(device, non_blocking=True)\n        dst_b = dst_all[sub].to(device, non_blocking=True)\n        ts_b  = ts_all[sub].to(device,  non_blocking=True)\n        x_b   = x_all[sub].to(device,   non_blocking=True)\n        y_b   = y_all[sub].to(device,   non_blocking=True)\n        cats_b = {k: v[sub].to(device, non_blocking=True) for k, v in cat_all.items()}\n\n        # ---- forward ----\n        out, raw_msg = model(src_b, dst_b, ts_b, x_b, **cats_b)\n        loss = criterion(out, y_b)\n\n        # ---- backward / step ----\n        if training:\n            optimizer.zero_grad(set_to_none=True)\n            loss.backward()\n            optimizer.step()\n\n        # ---- memory update (always use device tensors) ----\n        if hasattr(model, \"memory\"):\n            with torch.no_grad():\n                # Use the *device* batch tensors, never CPU versions:\n                model.memory.update_state(src_b, dst_b, ts_b, raw_msg.detach())\n\n        # ---- book-keeping ----\n        total_loss += float(loss.detach()) * bsz\n        n += bsz\n        preds.append(out.detach().float().cpu())\n        labels.append(y_b.detach().float().cpu())\n\n    pred = torch.cat(preds) if preds else torch.empty(0)\n    true = torch.cat(labels) if labels else torch.empty(0)\n    avg_loss = total_loss / max(n, 1)\n    return pred, true, avg_loss","metadata":{"_uuid":"7daed008-1eff-4622-9064-7f55364c43f4","_cell_guid":"9a1da0f1-7f7b-466e-aae9-7a5eed5c7ead","trusted":true,"collapsed":false,"jupyter":{"outputs_hidden":false}},"outputs":[],"execution_count":null}]}